const express = require("express");
const { pool } = require("./db");
const { parseTokens, requireAuth } = require("./auth");

const tokens = parseTokens(process.env.API_TOKENS);

const app = express();
app.use(express.json());

// Wraps an async route handler so a rejected promise reaches the error
// middleware instead of crashing the process (Express 4 doesn't do this
// on its own).
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// One JSON line per request. Path only, never the query string (that's
// where the patient email lives) or the body.
//
// Uses req.originalUrl, not req.path: a mounted middleware that responds
// without calling next() (e.g. a 401 from requireAuth below) leaves
// req.url/req.path rewritten relative to its mount point for the rest of
// the request, which would otherwise log "/patients" instead of
// "/api/patients". originalUrl is set once and never rewritten.
app.use((req, res, next) => {
  const start = process.hrtime.bigint();
  const path = req.originalUrl.split("?")[0];
  res.on("finish", () => {
    const duration_ms = Number(process.hrtime.bigint() - start) / 1e6;
    console.log(
      JSON.stringify({
        method: req.method,
        path,
        status: res.statusCode,
        duration_ms: Math.round(duration_ms),
        actor: req.actor || null,
      })
    );
  });
  next();
});

// No auth, no DB query — this is what the uptime check hits, and it must
// not keep a scale-to-zero DB warm.
app.get("/healthz", (_req, res) => {
  res.status(200).json({ ok: true });
});

app.use("/api", requireAuth(tokens));

// Ops summary: how many patients, how many reminders waiting.
app.get(
  "/api/summary",
  asyncHandler(async (_req, res) => {
    const patients = await pool.query("SELECT count(*)::int AS n FROM patients");
    const queued = await pool.query(
      "SELECT count(*)::int AS n FROM reminders WHERE status = 'queued'"
    );
    res.json({
      patients: patients.rows[0].n,
      queued_reminders: queued.rows[0].n,
    });
  })
);

// Look a patient up by email. Used by the care team to find someone fast.
app.get(
  "/api/patients",
  asyncHandler(async (req, res) => {
    const email = req.query.email || "";
    const result = await pool.query(
      "SELECT id, full_name, email, dob FROM patients WHERE email = $1",
      [email]
    );
    // Audit line: who looked up what, and how many rows came back — never
    // the email or the row data itself.
    console.log(
      JSON.stringify({
        event: "patient_lookup",
        actor: req.actor,
        results: result.rows.length,
      })
    );
    res.json(result.rows);
  })
);

function isPositiveInt(value) {
  return Number.isInteger(value) && value > 0;
}

function isValidChannel(value) {
  return value === "email" || value === "sms";
}

function isValidIsoDate(value) {
  if (typeof value !== "string" || !value) return false;
  return !Number.isNaN(new Date(value).getTime());
}

// Queue a reminder for a patient.
app.post(
  "/api/reminders",
  asyncHandler(async (req, res) => {
    const { patient_id, channel, send_at } = req.body || {};
    if (!isPositiveInt(patient_id)) {
      return res.status(400).json({ error: "patient_id must be a positive integer" });
    }
    if (!isValidChannel(channel)) {
      return res.status(400).json({ error: "channel must be 'email' or 'sms'" });
    }
    if (!isValidIsoDate(send_at)) {
      return res.status(400).json({ error: "send_at must be a valid ISO date" });
    }
    const result = await pool.query(
      "INSERT INTO reminders (patient_id, channel, send_at, status) VALUES ($1, $2, $3, 'queued') RETURNING id",
      [patient_id, channel, send_at]
    );
    res.json({ id: result.rows[0].id });
  })
);

// Error middleware: never lets a handler failure crash the process, never
// logs row data — just the error message.
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  console.error(JSON.stringify({ level: "error", message: err.message }));
  res.status(500).json({ error: "internal_error" });
});

module.exports = app;

"""
Reminder notifier.

Sends each due reminder through the messaging provider, then (optionally)
writes a no-PII receipt to S3. Two entry points:

  - main()             loop for local/dev use; reconnects if the DB drops
  - handler(event, ctx) single pass for AWS Lambda: connect, run once, close
"""
import json
import logging
import os
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

import boto3
import psycopg2

logging.basicConfig(level=logging.INFO, format="%(message)s")
log = logging.getLogger("notifier")

DATABASE_URL = os.environ.get(
    "DATABASE_URL", "postgresql://postgres:postgres@127.0.0.1:5432/wellis"
)

# Empty MESSAGING_URL means dry-run: log instead of calling a real provider.
MESSAGING_URL = os.environ.get("MESSAGING_URL", "")
MESSAGING_KEY = os.environ.get("MESSAGING_KEY", "")

# No default bucket — a missing var must skip the receipt, never fall back
# to a real one.
RECEIPT_BUCKET = os.environ.get("RECEIPT_BUCKET", "")


def connect():
    return psycopg2.connect(DATABASE_URL)


def fetch_due(conn):
    cur = conn.cursor()
    cur.execute(
        "SELECT r.id, r.channel, p.email "
        "FROM reminders r JOIN patients p ON p.id = r.patient_id "
        "WHERE r.status = 'queued' AND r.send_at <= now() "
        "ORDER BY r.send_at LIMIT 50"
    )
    return cur.fetchall()


def send_one(rid, channel, email):
    """Returns True if the send succeeded (dry-run counts as success)."""
    if not MESSAGING_URL:
        log.info(json.dumps({"event": "send_dry_run", "reminder_id": rid, "channel": channel}))
        return True

    payload = json.dumps({"to": email, "channel": channel}).encode()
    req = urllib.request.Request(
        MESSAGING_URL,
        data=payload,
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {MESSAGING_KEY}",
        },
    )
    try:
        urllib.request.urlopen(req, timeout=5)
        return True
    except Exception as exc:  # noqa: BLE001 - one bad send must not stop the batch
        log.warning(
            json.dumps(
                {"event": "send_failed", "reminder_id": rid, "channel": channel, "error": str(exc)}
            )
        )
        return False


def write_receipt(sent):
    """sent: list of (id, channel). No PII — ids and channel only."""
    if not RECEIPT_BUCKET:
        return
    body = json.dumps(
        {
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "reminders": [
                {"id": rid, "channel": channel, "status": "sent"} for rid, channel in sent
            ],
        }
    )
    try:
        client = boto3.client("s3")
        client.put_object(
            Bucket=RECEIPT_BUCKET, Key=f"receipts/{int(time.time())}.json", Body=body.encode()
        )
    except Exception as exc:  # noqa: BLE001 - a receipt failure must not crash the run
        log.warning(json.dumps({"event": "receipt_failed", "error": str(exc)}))


def run_once(conn):
    """Processes due reminders. Returns {"due", "sent", "failed"} counts."""
    rows = fetch_due(conn)
    sent = []
    failed = 0
    for rid, channel, email in rows:
        if send_one(rid, channel, email):
            cur = conn.cursor()
            cur.execute("UPDATE reminders SET status = 'sent' WHERE id = %s", (rid,))
            conn.commit()
            sent.append((rid, channel))
            log.info(json.dumps({"event": "sent", "reminder_id": rid, "channel": channel}))
        else:
            # Left as 'queued' on purpose — the next run retries it.
            failed += 1

    if sent:
        write_receipt(sent)

    counts = {"due": len(rows), "sent": len(sent), "failed": failed}
    log.info(json.dumps({"event": "run_complete", **counts}))
    return counts


def main():
    conn = connect()
    try:
        while True:
            try:
                run_once(conn)
            except psycopg2.OperationalError as exc:
                log.warning(json.dumps({"event": "db_reconnect", "error": str(exc)}))
                try:
                    conn.close()
                except Exception:  # noqa: BLE001
                    pass
                conn = connect()
            time.sleep(30)
    finally:
        conn.close()


def handler(event, context):  # noqa: ARG001 - Lambda calling convention
    conn = connect()
    try:
        return run_once(conn)
    finally:
        conn.close()


if __name__ == "__main__":
    main()

