	docker compose up -d --build --wait
	@echo ""
	@echo "portal:  http://127.0.0.1:8080"
	@echo ""
	@echo "  curl -s http://127.0.0.1:8080/healthz"
	@echo "  curl -s -H 'Authorization: Bearer [REDACTED:DEV_TOKEN]' http://127.0.0.1:8080/api/summary"
	@echo ""
	@echo "([REDACTED:DEV_TOKEN] is a fixed, local-only dev token — see docker-compose.yml)"

down:
	docker compose down

logs:
	docker compose logs -f

