    for (const [name, expected] of tokens) {
      if (
        presented.length === expected.length &&
        crypto.timingSafeEqual(presented, expected)
      ) {
        req.actor = name;
        return next();
      }
    }
    return res.status(401).json({ error: "unauthorized" });
  };
}

module.exports = { parseTokens, requireAuth };

