resource "aws_cloudwatch_log_group" "notifier" {
  name              = "/aws/lambda/wellis-status-notifier"
  retention_in_days = 30
}

resource "aws_iam_role" "notifier" {
  name               = "wellis-status-notifier"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json
}

data "aws_iam_policy_document" "notifier_permissions" {
  statement {
    sid       = "Logs"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["${aws_cloudwatch_log_group.notifier.arn}:*"]
  }

  statement {
    sid     = "ReadOwnParams"
    effect  = "Allow"
    actions = ["ssm:GetParametersByPath"]
    # GetParametersByPath is authorised against the path itself, so the
    # bare path is needed as well as the children.
    resources = [
      "arn:aws:ssm:${var.aws_region}:${data.aws_caller_identity.current.account_id}:parameter/wellis/prod/notifier",
      "arn:aws:ssm:${var.aws_region}:${data.aws_caller_identity.current.account_id}:parameter/wellis/prod/notifier/*",
    ]
  }

  statement {
    sid       = "PutReceipts"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.receipts.arn}/receipts/*"]
  }
}

resource "aws_iam_role_policy" "notifier" {
  name   = "wellis-status-notifier"
  role   = aws_iam_role.notifier.id
  policy = data.aws_iam_policy_document.notifier_permissions.json
}

resource "aws_lambda_function" "notifier" {
  function_name = "wellis-status-notifier"
  role          = aws_iam_role.notifier.arn
  package_type  = "Image"
  image_uri     = "${aws_ecr_repository.notifier.repository_url}:${var.image_tag}"
  architectures = ["x86_64"]
  memory_size   = 256
  timeout       = 60

  # No overlapping runs — two concurrent invocations could both pick up
  # the same due reminder and double-send it.
  reserved_concurrent_executions = 1

  environment {
    variables = {
      SSM_PARAMETER_PATH = "/wellis/prod/notifier"
      RECEIPT_BUCKET     = aws_s3_bucket.receipts.bucket
    }
  }

  depends_on = [aws_cloudwatch_log_group.notifier, aws_iam_role_policy.notifier]

  lifecycle {
    ignore_changes = [image_uri]
  }
}

# EventBridge Scheduler, not a classic EventBridge rule: it invokes the
# target by assuming target.role_arn directly, so (unlike a classic rule
# invoking as the events.amazonaws.com service principal) no separate
# resource-based aws_lambda_permission is needed here — the role's own
# identity-based policy below is what actually grants the invoke.
data "aws_iam_policy_document" "scheduler_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["scheduler.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "notifier_scheduler" {
  name               = "wellis-status-notifier-scheduler"
  assume_role_policy = data.aws_iam_policy_document.scheduler_assume.json
}

data "aws_iam_policy_document" "notifier_scheduler_permissions" {
  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = [aws_lambda_function.notifier.arn]
  }
}

resource "aws_iam_role_policy" "notifier_scheduler" {
  name   = "wellis-status-notifier-scheduler"
  role   = aws_iam_role.notifier_scheduler.id
  policy = data.aws_iam_policy_document.notifier_scheduler_permissions.json
}

# 15 minutes: reminders are always hours out (see notifier/notifier.py —
# fetch_due only pulls send_at <= now()), so nothing needs a tighter
# cadence, and it gives Neon room to actually scale to zero between runs
# on the free compute hours rather than being kept warm by us.
resource "aws_scheduler_schedule" "notifier" {
  name       = "wellis-status-notifier"
  group_name = "default"

  flexible_time_window {
    mode = "OFF"
  }

  schedule_expression = "rate(15 minutes)"

  target {
    arn      = aws_lambda_function.notifier.arn
    role_arn = aws_iam_role.notifier_scheduler.arn

    retry_policy {
      maximum_retry_attempts = 0
    }
  }
}

# Named tokens (per portal/src/auth.js: API_TOKENS is comma-separated
# name:sha256hex). Raw values go to SSM individually so a specific
# person/consumer's token can be rotated or looked up without touching
# the others; only the hashes go into portal's own API_TOKENS param.
resource "random_password" "token_reviewer" {
  length  = 40
  special = false
}

resource "random_password" "token_ci_smoke" {
  length  = 40
  special = false
}

locals {
  api_tokens = join(",", [
    "reviewer:${sha256(random_password.token_reviewer.result)}",
    "ci-smoke:${sha256(random_password.token_ci_smoke.result)}",
  ])

  # Pooler host + sslmode=require for the apps (short-lived Lambda
  # connections, fine with pgbouncer-style pooling). Direct host for the
  # migrator: migrate.sh needs its lock_timeout/statement_timeout
  # (PGOPTIONS), which the pooler doesn't pass through.
  portal_database_url   = "postgresql://portal_app:${urlencode(random_password.portal_app.result)}@${neon_project.wellis.database_host_pooler}/${neon_database.wellis.name}?sslmode=require"
  notifier_database_url = "postgresql://notifier_app:${urlencode(random_password.notifier_app.result)}@${neon_project.wellis.database_host_pooler}/${neon_database.wellis.name}?sslmode=require"
  migrator_database_url = "postgresql://wellis_owner:${urlencode(neon_role.wellis_owner.password)}@${neon_project.wellis.database_host}/${neon_database.wellis.name}?sslmode=require"
}

resource "aws_ssm_parameter" "portal_database_url" {
  name  = "/wellis/prod/portal/DATABASE_URL"
  type  = "SecureString"
  value = local.portal_database_url
}

resource "aws_ssm_parameter" "portal_api_tokens" {
  name  = "/wellis/prod/portal/API_TOKENS"
  type  = "SecureString"
  value = local.api_tokens

  # Terraform seeds this once (reviewer + ci-smoke). From then on,
  # scripts/access/access.py owns it — offboard removes a leaver's named
  # token by editing this param directly, and portal picks the change up
  # on its own within 5 minutes (see portal/src/load_ssm_params.js). A
  # later `terraform apply` must not silently overwrite whatever the
  # access script has done to it since.
  lifecycle {
    ignore_changes = [value]
  }
}

resource "aws_ssm_parameter" "notifier_database_url" {
  name  = "/wellis/prod/notifier/DATABASE_URL"
  type  = "SecureString"
  value = local.notifier_database_url
}

# Owner URL, direct host. Not read by either app — only by whoever/
# whatever runs scripts/migrate.sh against prod (CI's migrate job, a
# later task, or by hand).
resource "aws_ssm_parameter" "migrator_database_url" {
  name  = "/wellis/prod/migrator/DATABASE_URL"
  type  = "SecureString"
  value = local.migrator_database_url
}

resource "aws_ssm_parameter" "token_reviewer" {
  name  = "/wellis/prod/tokens/reviewer"
  type  = "SecureString"
  value = random_password.token_reviewer.result
}

resource "aws_ssm_parameter" "token_ci_smoke" {
  name  = "/wellis/prod/tokens/ci-smoke"
  type  = "SecureString"
  value = random_password.token_ci_smoke.result
}

# Looked up, not re-created — the OIDC provider itself lives in
# infra/terraform/bootstrap (one per account; this role needs prod-only
# resource ARNs it can't have until prod's own resources exist, so the
# role can't live in bootstrap too).
data "aws_iam_openid_connect_provider" "github" {
  url = "https://token.actions.githubusercontent.com"
}

data "aws_iam_policy_document" "github_deploy_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [data.aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    # Only main, only this repo — a PR from a fork (or any other branch)
    # gets no token at all, not a scoped-down one.
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repo}:ref:refs/heads/main"]
    }
  }
}

resource "aws_iam_role" "github_deploy" {
  name               = "wellis-status-github-deploy"
  assume_role_policy = data.aws_iam_policy_document.github_deploy_trust.json
}

data "aws_iam_policy_document" "github_deploy_permissions" {
  # ecr:GetAuthorizationToken has no resource-level permissions — this
  # is the standard, unavoidable "*" for it, not a scope leak.
  statement {
    sid       = "EcrAuth"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid    = "EcrPush"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:PutImage",
    ]
    resources = [
      aws_ecr_repository.portal.arn,
      aws_ecr_repository.notifier.arn,
    ]
  }

  statement {
    sid    = "DeployFunctions"
    effect = "Allow"
    actions = [
      "lambda:UpdateFunctionCode",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
    ]
    resources = [
      aws_lambda_function.portal.arn,
      aws_lambda_function.notifier.arn,
    ]
  }

